:root{--mjl-auth-navy:#16324f;--mjl-auth-blue:#164f7a;--mjl-auth-support:#7fb3d5;--mjl-auth-page:#f5f7f8;--mjl-auth-text:#202529;--mjl-auth-muted:#5c6870;--mjl-auth-border:#c8d0d5;--mjl-auth-error:#8a1c1c;--mjl-auth-error-bg:#fdecec;--mjl-auth-success:#17633a;--mjl-auth-success-bg:#e8f5ec}
*{box-sizing:border-box}.mjl-auth-page{background:var(--mjl-auth-page);color:var(--mjl-auth-text);font-family:Inter,Arial,Helvetica,sans-serif;margin:0;min-height:100vh}.mjl-auth-shell{display:grid;grid-template-columns:minmax(260px,19.5vw) 1fr;min-height:100vh}.mjl-auth-sidebar{background:linear-gradient(180deg,#183957,var(--mjl-auth-navy));overflow:hidden;position:relative}.mjl-auth-sidebar span{border:1px solid rgba(127,179,213,.35);border-bottom:0;border-radius:180px 180px 0 0;bottom:-18%;height:80%;left:var(--left);position:absolute;transform:rotate(-14deg);width:60%}.mjl-auth-sidebar span:nth-child(1){--left:-13%;height:82%;width:112%}.mjl-auth-sidebar span:nth-child(2){--left:15%;height:72%;width:92%}.mjl-auth-sidebar span:nth-child(3){--left:39%;height:62%;width:76%}.mjl-auth-sidebar span:nth-child(4){--left:60%;height:52%;width:62%}.mjl-auth-content{display:grid;grid-template-rows:auto 1fr;min-width:0}.mjl-auth-header{align-items:center;display:flex;height:92px;padding:28px 36px}.mjl-auth-logo{align-items:center;color:var(--mjl-auth-navy);display:inline-flex;font-size:22px;gap:10px;text-decoration:none}.mjl-auth-logo span{align-items:center;background:var(--mjl-auth-navy);border-radius:9px;color:#fff;display:inline-flex;font-size:21px;font-weight:700;height:36px;justify-content:center;width:36px}.mjl-auth-main{align-items:center;display:flex;justify-content:center;padding:24px 32px 92px}.mjl-auth-panel{background:#fff;border:1px solid var(--mjl-auth-border);border-radius:16px;box-shadow:none;max-width:480px;padding:36px;width:100%}.mjl-auth-heading{margin-bottom:28px}.mjl-auth-heading h1{color:var(--mjl-auth-navy);font-size:28px;font-weight:700;letter-spacing:-.02em;line-height:1.2;margin:0}.mjl-auth-heading p{color:var(--mjl-auth-muted);font-size:15px;line-height:1.5;margin:12px 0 0}.mjl-auth-heading strong{color:#34414a;font-weight:500}.mjl-auth-field{margin:0 0 20px}.mjl-auth-field label{display:block;font-size:13px;font-weight:600;margin-bottom:8px}.mjl-auth-field input{background:#fff;border:1px solid #5c6870;border-radius:9px;color:var(--mjl-auth-text);font:inherit;height:46px;padding:10px 13px;width:100%}.mjl-auth-field input[aria-invalid=true]{border-color:var(--mjl-auth-error);box-shadow:0 0 0 1px var(--mjl-auth-error)}.mjl-auth-password{position:relative}.mjl-auth-password input{padding-right:48px}.mjl-auth-password button{align-items:center;background:transparent;border:0;color:var(--mjl-auth-muted);cursor:pointer;display:flex;height:44px;justify-content:center;position:absolute;right:1px;top:1px;width:44px}.mjl-auth-forgot{text-align:right;margin:-6px 0 26px}.mjl-auth-button{background:var(--mjl-auth-blue);border:1px solid var(--mjl-auth-blue);border-radius:8px;color:#fff;cursor:pointer;display:block;font:inherit;font-size:14px;font-weight:700;min-height:46px;padding:11px 16px;text-align:center;text-decoration:none;width:100%}.mjl-auth-button:disabled{background:#dfe6ea;border-color:#c8d0d5;color:#5c6870;cursor:not-allowed}.mjl-auth-link{background:transparent;border:0;color:var(--mjl-auth-blue);cursor:pointer;font:inherit;font-size:13px;font-weight:600;padding:0;text-decoration:none}.mjl-auth-message{border-radius:8px;font-size:14px;line-height:1.4;margin:0 0 20px;padding:11px 13px}.mjl-auth-message span{display:block}.mjl-auth-error{background:var(--mjl-auth-error-bg);color:var(--mjl-auth-error)}.mjl-auth-success{background:var(--mjl-auth-success-bg);color:var(--mjl-auth-success)}.mjl-auth-secondary{color:var(--mjl-auth-muted);font-size:13px;margin-top:26px;text-align:center}.mjl-auth-return{display:block;margin-top:26px;text-align:center}.mjl-otp-control{height:50px;position:relative}.mjl-otp-slots{align-items:center;display:grid;gap:7px;grid-template-columns:repeat(3,44px) 20px repeat(3,44px);justify-content:start}.mjl-otp-slots span{align-items:center;background:#fff;border:1px solid #5c6870;border-radius:8px;color:var(--mjl-auth-navy);display:flex;font-size:20px;font-weight:600;height:50px;justify-content:center}.mjl-otp-slots i{color:var(--mjl-auth-muted);font-style:normal;text-align:center}.mjl-otp-control input{background:transparent;border:0;color:transparent;height:50px;inset:0;letter-spacing:40px;opacity:.02;position:absolute;width:100%}.mjl-otp-control:focus-within .mjl-otp-slots span:first-of-type{outline:3px solid rgba(22,79,122,.22);outline-offset:1px}.mjl-password-rules{display:flex;flex-wrap:wrap;gap:7px;list-style:none;margin:4px 0 24px;padding:0}.mjl-password-rule{background:#fff;border:1px solid var(--mjl-auth-border);border-radius:6px;color:var(--mjl-auth-muted);font-size:12px;padding:5px 8px}.mjl-password-rule[data-valid=true]{background:#eaf3f8;border-color:var(--mjl-auth-support);color:var(--mjl-auth-blue)}.mjl-auth-readonly{background:#eaf3f8;border-radius:8px;color:var(--mjl-auth-text);font-size:14px;margin-bottom:24px;padding:12px 14px}.mjl-auth-readonly small{color:var(--mjl-auth-muted);display:block;margin-bottom:5px}.mjl-auth-field-error{color:var(--mjl-auth-error);display:block;font-size:12px;margin-top:6px}.mjl-auth-page :where(a,button,input):focus-visible{outline:3px solid var(--mjl-auth-support);outline-offset:3px}@media(hover:hover){.mjl-auth-button:hover{background:#123f62}.mjl-auth-link:hover{text-decoration:underline}}@media(max-width:760px){.mjl-auth-shell{display:block}.mjl-auth-sidebar{display:none}.mjl-auth-header{height:78px;padding:22px 20px}.mjl-auth-main{align-items:flex-start;padding:28px 16px 48px}.mjl-auth-panel{padding:28px 22px}.mjl-otp-slots{gap:5px;grid-template-columns:repeat(3,minmax(36px,44px)) 14px repeat(3,minmax(36px,44px));justify-content:center}}@media(forced-colors:active){.mjl-auth-button,.mjl-auth-logo span{forced-color-adjust:none}.mjl-password-rule[data-valid=true]{border-width:2px}}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}
